assert len(source) == 24
assert len(drafts) == 24
answer = []
for article in source:
    xml, reason, notes = drafts[article['number']]
    entry = {key: article[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    entry.update(proposed_xml=xml, reason=reason, review_notes=notes, status='rewrite_draft')
    answer.append(entry)
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answer)} articles')
